def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        try:
            if value is None:
                return default
            return (int(value[0]), int(value[1]))
        except Exception:
            return default

    def items(value):
        try:
            return list(value) if value is not None else []
        except Exception:
            return []

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for t in items(targets):
            p = pos(t, None)
            if p is None:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = p
        return best

    def farthest(targets, sx, sy):
        best = None
        best_d = None
        for t in items(targets):
            p = pos(t, None)
            if p is None:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best_d is None or d > best_d:
                best_d = d
                best = p
        return best

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"))
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = farthest(corners, ox, oy)
