            return away
        return toward_corner

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("frontier_cells")
        target = nearest(targets, sx, sy)
        if target is not None:
            return step_toward((sx, sy), target)
        center = (w // 2 if w else sx, h // 2 if h else sy)
        return step_toward((sx, sy), center)

    resources = observation.get("resources")
    target = nearest(resources, sx, sy)
    if target is not None:
        return step_toward((sx, sy), target)

    enemy = (ox, oy)
    if ox == sx and oy == sy:
        return [0, 0]
    return step_toward((sx, sy), enemy)

